using System.Diagnostics;using System.IO;using System.Text.Json;using System.Windows;namespace LexCityLauncher;public partial class MainWindow:Window{readonly Config C;public MainWindow(){InitializeComponent();C=Config.Load();NickBox.Text=C.Nick;PlayersText.Text=$"  •  {C.Host}:{C.Port}";}void Play_Click(object s,RoutedEventArgs e){if(string.IsNullOrWhiteSpace(NickBox.Text)){MessageText.Text="Digite seu nick.";return;}C.Nick=NickBox.Text.Trim();C.Save();var exe=Path.Combine(AppContext.BaseDirectory,"samp.exe");if(!File.Exists(exe)){MessageText.Text="samp.exe não encontrado.";MessageBox.Show("Coloque samp.exe na mesma pasta do launcher.","Cliente não encontrado");return;}Process.Start(new ProcessStartInfo(exe,$"{C.Host}:{C.Port}"){UseShellExecute=true});MessageText.Text="Iniciando o cliente...";}void Verify_Click(object s,RoutedEventArgs e){UpdateProgress.Value=100;UpdateText.Text="Verificação concluída.";}void Settings_Click(object s,RoutedEventArgs e){var d=new SettingsWindow(C);if(d.ShowDialog()==true){C.Save();PlayersText.Text=$"  •  {C.Host}:{C.Port}";MessageText.Text="Configurações salvas.";}}void Discord_Click(object s,RoutedEventArgs e){try{Process.Start(new ProcessStartInfo(C.Discord){UseShellExecute=true});}catch{}}}public class Config{public string Host{get;set;}="127.0.0.1";public int Port{get;set;}=7777;public string Nick{get;set;}="";public string Discord{get;set;}="https://discord.com/";static string P=>Path.Combine(AppContext.BaseDirectory,"launcher.json");public static Config Load(){try{if(File.Exists(P))return JsonSerializer.Deserialize<Config>(File.ReadAllText(P))??new();}catch{}return new();}public void Save()=>File.WriteAllText(P,JsonSerializer.Serialize(this,new JsonSerializerOptions{WriteIndented=true}));}
